<script setup>import {ref} from 'vue';import {useStudy} from '../stores/study';import PageHeading from '../components/PageHeading.vue';import GoalEditor from '../components/GoalEditor.vue';import ProgressBar from '../components/ProgressBar.vue';import QuoteCard from '../components/QuoteCard.vue';import ToastMessage from '../components/ToastMessage.vue';const s=useStudy(),toast=ref('');function save(){toast.value='学习目标已保存！';setTimeout(()=>toast.value='',2000)}const badges=[{days:3,name:'起步小勇士',desc:'连续学习 3 天，建立好习惯。',icon:'✧'},{days:7,name:'坚持小达人',desc:'连续学习 7 天，让努力成为日常。',icon:'★'},{days:30,name:'自律闪闪星',desc:'连续学习 30 天，收获更好的自己。',icon:'✿'}]</script><template><section><PageHeading eyebrow="YOUR GOALS" title="为自己设定一个小目标" subtitle="不和别人比较，只和昨天的自己比一比。"/><div class="goal-hero"><div><small class="eyebrow">KEEP GOING</small><h2>你已经比昨天更进一步了。🌱</h2><p>每一次认真学习，都是送给未来自己的礼物。</p></div><div class="hero-art">◎<span>✦</span></div></div><GoalEditor v-model="s.state.value.goal" @save="save"/><div class="content-grid"><section class="panel"><div class="panel-heading"><div><small class="eyebrow">TODAY'S GOAL</small><h2>今日目标进度</h2></div></div><ProgressBar :value="Math.min(100,Math.round(s.minutes.value/Math.max(1,s.state.value.goal)*100))" :label="`${s.minutes.value} / ${s.state.value.goal} 分钟`"/><p class="muted">小目标不是压力，而是帮助你稳稳前进的方向。</p><div class="goal-tip">♡ 如果今天状态不佳，也没关系。休息好，再重新出发。</div></section><aside class="panel streak-panel"><span class="streak-icon">♨</span><small class="eyebrow">CURRENT STREAK</small><strong>{{s.state.value.streak}} <small>天</small></strong><h3>连续打卡中</h3><p>坚持本身就很了不起！</p><button class="secondary" @click="s.state.value.streak++">✦ 模拟完成一天打卡</button><small class="muted">课堂演示按钮：连续天数 +1</small></aside></div><section class="panel category-panel"><div class="panel-heading"><div><small class="eyebrow">MILESTONES</small><h2>坚持成就</h2></div></div><div class="milestones"><article v-for="b in badges" :key="b.days" class="badge-card" :class="{unlocked:s.state.value.streak>=b.days}"><span>{{b.icon}}</span><b>{{b.name}}</b><p>{{b.desc}}</p><small>{{s.state.value.streak>=b.days?'已解锁 ✓':`连续 ${b.days} 天解锁`}}</small></article></div></section><QuoteCard quote="慢慢来比较快，持续做比偶尔做得完美更重要。" author="写给正在努力的你"/><ToastMessage :message="toast"/></section></template>